1264	  if (!lit) pushLog('warn', 'kit_violation: no torch for the shelter dig-in — sealing dark');
1265	  const feet = bot.entity.position.floored();
1266	  const cap = feet.offset(0, 2, 0);
1267	  // #105 (live-caught, ShltrQA fixture): the cap has NO reference on its own — on ANY flat
1268	  // ground (natural or artificial), `feet.offset(0,2,0)` is exactly where the bot originally
1269	  // stood, one head-height above open air on every side, same as `branchWallOff`'s own roof
1270	  // cell (survival.js, "no orthogonal reference on open ground"). WALL_OFF solves this by
1271	  // placing its 4 head-level RING cells first — each of THOSE has a reference (the wall block
1272	  // directly below it), and the center cap then references the ring. Dig-in has no ring built
1273	  // (the shaft's own natural walls at feet/head level are untouched terrain, not a placed
1274	  // wall), so it needs the same one-cell-wide ring at cap height before the cap itself is
1275	  // placeable — each ring cell's OWN reference is the natural ground one level down and one
1276	  // column over, which IS solid on ordinary terrain (confirmed live: a 3x3 dirt platform's
